#!/usr/bin/env bash
# Standalone serve script for the handover package.
#
# NOT the same as scripts/serve_dbbahn_fp8_eagle3.sh in the bench repo: that one
# is generated by bench.server and uses a path relative to the bench checkout
# (./models/...), which does not exist outside it. This one locates the
# checkpoint next to itself, so it works wherever the package is copied to.
#
#   cp -r /data/handover/qwen3-4b-dbbahn-fp8-eagle3 ~/
#   bash ~/qwen3-4b-dbbahn-fp8-eagle3/serve_handover.sh
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MODEL="$HERE/qwen3-4b-dbbahn-FP8-DYNAMIC"

[ -d "$MODEL" ] || { echo "no checkpoint at $MODEL"; exit 1; }

# The FlashInfer sampler hangs the vLLM 0.21 engine on the GB10 when a batch
# samples at temperature > 0. Greedy requests never reach the sampler, so this
# only changes which kernel does top-k/top-p -- but set it on every server in a
# comparison, or the two differ by more than the thing under test.
export VLLM_USE_FLASHINFER_SAMPLER=0

# No --quantization flag: vLLM reads the compressed-tensors block out of
# config.json.
#
# The four flags below are pinned deliberately. Use the SAME values on the BF16
# server you compare against, especially --gpu-memory-utilization: FP8 weights
# are about half the size, so at the same utilization this server would
# otherwise receive a much larger KV cache and get credited for it. Record the
# "GPU KV cache size: N tokens" line each server prints at startup and check
# they are comparable.
#
# Drop --speculative-config to measure FP8 alone. That third data point is what
# separates "what quantization cost me" from "what speculation gained me" --
# and note EAGLE-3 is output-lossless at greedy while FP8 is not, so any
# behavioural difference you find belongs to the quantization.
exec vllm serve "$MODEL" \
    --served-model-name qwen3-4b-dbbahn \
    --host 0.0.0.0 --port 8000 \
    --max-model-len 16384 \
    --gpu-memory-utilization 0.9 \
    --max-num-seqs 256 \
    --dtype auto \
    --seed 0 \
    --speculative-config '{"method": "eagle3", "model": "AngelSlim/Qwen3-4B_eagle3", "num_speculative_tokens": 3}' \
    --no-enable-prefix-caching \
    "$@"
